fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine the number of participants to consider
    let count = participations.iter().take(n as usize).filter(|&&attendance| {
        // Check if the participant is eligible
        5 - attendance >= k
    }).count();
    
    // Calculate the maximum number of teams of 3
    (count / 3) as u8
}

// Example usage
fn main() {
    let n = 5;
    let k = 2;
    let participations = vec![1, 2, 3, 4, 5, 0];
    let result = solve(n, k, participations);
    println!("Maximum number of teams: {}", result); // Output: Maximum number of teams: 1
}